#define PCSX2_TEXTURE_FILTERING_INFO_0_CHS "“双线性 (PS2)”模式还原实机效果；“强制”模式则对所有纹理进行平滑处理。"
#define OPTION_VAL_NEAREST_CHS "最邻"
